import type {
  GradientDef,
  GradientLayer,
  GradientStop,
} from "../../../../../../../../../../shared/libs/ui/types";
import { colorCssVar } from "./colorTaxonomy";

/**
 * Render a `GradientDef` as a CSS `background` value. Used for live previews
 * in the editor — production CSS is generated by the engine, not this fn.
 *
 *   GradientDef = GradientLayer | GradientLayer[]
 *
 * For arrays we emit a comma-separated stack of gradient functions (the
 * standard CSS layered-background syntax — first layer paints on top).
 *
 * Color stops resolve via `colorCssVar` so brand/status/etc tokens render
 * correctly without a full theme resolver here.
 */
export function gradientCss(g: GradientDef | undefined): string {
  if (!g) return "transparent";
  if (Array.isArray(g)) return g.map(gradientLayerCss).join(", ");
  return gradientLayerCss(g);
}

export function gradientLayerCss(layer: GradientLayer): string {
  const stops = layer.stops.map(formatStop).join(", ");
  if (layer.type === "linear") {
    return `linear-gradient(${formatAngle(layer.angle)}, ${stops})`;
  }
  if (layer.type === "radial") {
    const shape = layer.shape ?? "ellipse";
    const pos = layer.position ? ` at ${layer.position}` : "";
    return `radial-gradient(${shape}${pos}, ${stops})`;
  }
  // conic
  const from = layer.angle != null ? `from ${layer.angle}deg ` : "";
  const at = layer.position ? `at ${layer.position} ` : "";
  return `conic-gradient(${from}${at}, ${stops})`.replace(/ +/g, " ").replace(/\(\s+/g, "(");
}

function formatStop(s: GradientStop): string {
  const color = s.color === "transparent" ? "transparent" : colorCssVar(s.color);
  return s.position ? `${color} ${s.position}` : color;
}

function formatAngle(angle: number | string): string {
  if (typeof angle === "number") return `${angle}deg`;
  return angle;
}
